/// <summary>
/// Data contract class as a response for service <c>METPurchaseOrderCancelService</c>
/// </summary>
[DataContractAttribute]
class METPurchaseOrderLineResponseContract extends METBaseResponseContract
{
}

Method.Source:
    /// <summary>
    /// Contruct a new Response contract
    /// </summary>
    /// <param name = "_cancelResult">Result of the cancellation</param>
    /// <param name = "_cancelMessage">Message Result</param>
    /// <returns>new contract</returns>
    public static METPurchaseOrderLineResponseContract newFromParameters(METProcessingStatus _result, Description255 _message)
    {
        METPurchaseOrderLineResponseContract purchaseOrderLineResponse = new METPurchaseOrderLineResponseContract();

        purchaseOrderLineResponse.parmResult(enum2Symbol(enumNum(METProcessingStatus), enum2int(_result)));
        purchaseOrderLineResponse.parmMessage(_message);

        return purchaseOrderLineResponse;
    }
